mapper.select:
SELECT sc.id, sc.so_id, sc.code, sc.approve_status, sc.invalid_status, sc.approve_user_name, sc.create_user_name, sc.create_time, si.code AS soCode, si.customer_id, si.order_type, scd.sku_id, scd.sku_no, scd.qty, scd.old_qty, scd.amount, scd.currency_symbol, scd.old_currency_symbol, scd.old_amount FROM so_change sc INNER JOIN so_info si ON si.id=sc.so_id AND si.is_deleted=FALSE INNER JOIN so_change_detail scd ON sc.id=scd.main_id AND scd.is_deleted=FALSE WHERE sc.is_deleted=FALSE
AND sc.approve_status IN
#{approve}
AND scd.sku_no IN
#{skuNo}
AND sc.code ILIKE concat('%', #{params.code} ,'%')
AND si.so_code ILIKE concat('%', #{params.soCode} ,'%')
AND si.order_type =#{params.orderType}
AND sc.approve_status IN
#{approveStatus}
AND sc.invalid_status =#{params.invalidStatus}
AND si.customer_id IN
#{customerId}
AND sc.create_user_id IN
#{createUserId}
AND sc.create_time >= #{params.createTimeList[0]} and (#{params.createTimeList[1]}::TIMESTAMP + INTERVAL '1 DAY' ) > sc.create_time
${params.permissionSql}
ORDER BY sc.create_time DESC
